questions.starter:
// Create the Student class
// constructor(name, course, score)
// getGrade() method
// getSummary() method

// Create 2 instances and print summaries

questions.solution:
class Student {
  constructor(name, course, score) {
    this.name = name;
    this.course = course;
    this.score = score;
  }

  getGrade() {
    if (this.score >= 80) return 'A';
    if (this.score >= 60) return 'B';
    if (this.score >= 50) return 'C';
    return 'F';
  }

  getSummary() {
    return this.name + ' — ' + this.course + ' — ' + this.getGrade();
  }
}

const amara = new Student('Amara', 'JavaScript', 88);
const bayo = new Student('Bayo', 'Python', 45);

console.log(amara.getSummary());
console.log(bayo.getSummary());

questions.starter:
// Create BankAccount class with #balance
// getter and setter for balance (reject negative)
// deposit(amount) method

// Create instance, deposit, log balance
// try/catch: set negative balance, log error

questions.solution:
class BankAccount {
  #balance;

  constructor(ownerName, initialBalance) {
    this.ownerName = ownerName;
    this.#balance = initialBalance;
  }

  get balance() {
    return this.#balance;
  }

  set balance(value) {
    if (value < 0) throw new Error('Balance cannot be negative');
    this.#balance = value;
  }

  deposit(amount) {
    this.#balance += amount;
  }
}

const account = new BankAccount('Amara', 10000);
account.deposit(5000);
console.log(account.balance);

try {
  account.balance = -100;
} catch (e) {
  console.log(e.message);
}

