// Base class Vehicle: constructor(make, model, year)
// getInfo() method

// Subclass ElectricVehicle: extends Vehicle
// constructor adds range
// Override getInfo() to include range

// Create instances and print info

questions.solution:
class Vehicle {
  constructor(make, model, year) {
    this.make = make;
    this.model = model;
    this.year = year;
  }

  getInfo() {
    return this.make + ' ' + this.model + ' (' + this.year + ')';
  }
}

class ElectricVehicle extends Vehicle {
  constructor(make, model, year, range) {
    super(make, model, year);
    this.range = range;
  }

  getInfo() {
    return super.getInfo() + ' — Range: ' + this.range + 'km';
  }
}

const camry = new Vehicle('Toyota', 'Camry', 2022);
const tesla = new ElectricVehicle('Tesla', 'Model 3', 2023, 350);

console.log(camry.getInfo());
console.log(tesla.getInfo());

