// Class Product with #price
// getter, setter (validate 1–1000000)
// getPriceWithVAT() method

// Create instance, log VAT price
// try/catch: set price to 0

questions.solution:
class Product {
  #price;

  constructor(name, price) {
    this.name = name;
    this.#price = price;
  }

  get price() {
    return this.#price;
  }

  set price(value) {
    if (value < 1 || value > 1000000) {
      throw new Error('Price must be between 1 and 1000000');
    }
    this.#price = value;
  }

  getPriceWithVAT() {
    return this.#price * 1.075;
  }
}

const item = new Product('Earbuds', 5000);
console.log(item.getPriceWithVAT());

try {
  item.price = 0;
} catch (e) {
  console.log(e.message);
}

questions.starter:
// Base class Shape with getArea() returning 0
// Subclass Circle: constructor(radius), override getArea()
// Subclass Rectangle: constructor(width, height), override getArea()

// Create array with Circle(5) and Rectangle(4, 6)
// forEach: log each area

questions.solution:
class Shape {
  getArea() {
    return 0;
  }
}

class Circle extends Shape {
  constructor(radius) {
    super();
    this.radius = radius;
  }

  getArea() {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle extends Shape {
  constructor(width, height) {
    super();
    this.width = width;
    this.height = height;
  }

  getArea() {
    return this.width * this.height;
  }
}

const shapes = [new Circle(5), new Rectangle(4, 6)];
shapes.forEach(shape => console.log(shape.getArea()));

