// Class User: constructor(name, email), greet() method
// Subclass Admin: extends User, adds permissions array
// Override greet() using super.greet()

// Create instances and log greetings

questions.solution:
class User {
  constructor(name, email) {
    this.name = name;
    this.email = email;
  }

  greet() {
    return 'Hello, I am ' + this.name;
  }
}

class Admin extends User {
  constructor(name, email, permissions) {
    super(name, email);
    this.permissions = permissions;
  }

  greet() {
    return super.greet() + ' (Admin — ' + this.permissions.length + ' permissions)';
  }
}

const user = new User('Bayo', 'bayo@email.com');
const admin = new Admin('Amara', 'amara@email.com', ['read', 'write', 'delete']);

console.log(user.greet());
console.log(admin.greet());

