// Class TaskManager
// Static method createFromArray(arr)
// Returns array of {id, name, done} objects

// Call with 3 task names and log result

questions.solution:
class TaskManager {
  static createFromArray(arr) {
    return arr.map((name, index) => ({
      id: index + 1,
      name: name,
      done: false
    }));
  }
}

const tasks = TaskManager.createFromArray(['Buy groceries', 'Write code', 'Read book']);
console.log(tasks);

