// Class Playlist with #songs private array
// constructor(name)
// addSong(title), get songCount(), getSongs()

// Create playlist, add 3 songs
// Log count and songs

questions.solution:
class Playlist {
  #songs = [];

  constructor(name) {
    this.name = name;
  }

  addSong(title) {
    this.#songs.push(title);
  }

  get songCount() {
    return this.#songs.length;
  }

  getSongs() {
    return [...this.#songs];
  }
}

const myPlaylist = new Playlist('Afrobeats Hits');
myPlaylist.addSong('Essence');
myPlaylist.addSong('Last Last');
myPlaylist.addSong('Calm Down');

console.log(myPlaylist.songCount);
console.log(myPlaylist.getSongs());

questions.starter:
// Base class Notification: constructor(message), send()
// EmailNotification: extends, adds recipient, overrides send()
// SMSNotification: extends, adds phoneNumber, overrides send()

// Create array of mixed types, forEach log send()

questions.solution:
class Notification {
  constructor(message) {
    this.message = message;
  }

  send() {
    return 'Sending: ' + this.message;
  }
}

class EmailNotification extends Notification {
  constructor(message, recipient) {
    super(message);
    this.recipient = recipient;
  }

  send() {
    return 'Sending: ' + this.message + ' via email to ' + this.recipient;
  }
}

class SMSNotification extends Notification {
  constructor(message, phoneNumber) {
    super(message);
    this.phoneNumber = phoneNumber;
  }

  send() {
    return 'Sending: ' + this.message + ' via SMS to ' + this.phoneNumber;
  }
}

const notifications = [
  new EmailNotification('Welcome!', 'amara@email.com'),
  new SMSNotification('Your OTP is 1234', '08012345678')
];

notifications.forEach(n => console.log(n.send()));
